"""Run with:  python test_localization.py   (no Streamlit / PyTorch needed)"""
import copy
import recommendations as rec
from localization import (
    PLANT_AR, CONDITION_AR, STATUS_AR, ADVICE_AR, DISCLAIMER_AR, CLASS_AR,
    class_label, localize_recommendation, normalize_class_label,
)

missing = []

def need(table, text, kind):
    if text not in table:
        missing.append(f"[{kind}] {text!r}")

# Every record in the real database
payloads = list(rec.RECOMMENDATION_DB.values())
# Plus both fallback payloads generated by the function itself
payloads.append(rec.generate_smart_recommendations("Tomato_Healthy", 0.10))      # low confidence
payloads.append(rec.generate_smart_recommendations("Not_A_Real_Class", 0.99))    # unknown class
# Plus the standard disclaimer path
payloads.append(rec.generate_smart_recommendations("Tomato_Late_Blight", 0.99))

for p in payloads:
    need(PLANT_AR, p["plant"], "plant")
    need(CONDITION_AR, p["condition"], "condition")
    need(STATUS_AR, p["status"], "status")
    for line in p["recommendations"]:
        need(ADVICE_AR, line, "advice")
    if "disclaimer" in p:
        need(DISCLAIMER_AR, p["disclaimer"], "disclaimer")

# Every model class must have an Arabic label (14 classes = DB keys)
for key in rec.RECOMMENDATION_DB:
    if normalize_class_label(key) not in CLASS_AR:
        missing.append(f"[class] {key!r} -> {normalize_class_label(key)!r}")

assert not missing, "Missing Arabic translations:\n" + "\n".join(missing)

# The trailing-underscore class must now translate (was a silent miss before)
assert class_label("Corn_(maize)_Common_Rust_", arabic=True) == "الذرة - الصدأ الشائع"
assert class_label("Corn_(maize)_Common_Rust_", arabic=False) == "Corn (maize) Common Rust"

# Backend data must never be mutated by localisation
snapshot = copy.deepcopy(rec.RECOMMENDATION_DB)
for key in rec.RECOMMENDATION_DB:
    out = rec.generate_smart_recommendations(key, 0.99)
    before = copy.deepcopy(out)
    ar = localize_recommendation(out, arabic=True)
    assert out == before, "input dict was modified"
    assert len(ar["recommendations"]) == len(out["recommendations"])
    assert all(any("\u0600" <= ch <= "\u06FF" for ch in s) for s in ar["recommendations"]), key
assert rec.RECOMMENDATION_DB == snapshot

# English passthrough returns the identical object (no change at all)
e = rec.generate_smart_recommendations("Tomato_Healthy", 0.99)
assert localize_recommendation(e, arabic=False) is e

# Unknown text degrades gracefully to English
assert localize_recommendation({"plant": "Rose", "recommendations": ["x"]}, True)["plant"] == "Rose"

print(f"OK: {len(payloads)} payloads, {len(ADVICE_AR)} advice lines, {len(CLASS_AR)} classes - all translated, data unmodified.")
